describe('Checkout Form Responsiveness', () => {
    beforeEach(() => {
        cy.visit('/checkout');
        cy.viewport('iphone-6'); // Set viewport to mobile screen size
    });

    it('should display the checkout form stacked vertically on mobile screens', () => {
        cy.get('.checkout-form').should('be.visible');
        cy.get('.checkout-form .form-field').should('have.length.greaterThan', 1);
        cy.get('.checkout-form .form-field').each(($field) => {
            cy.wrap($field).should('have.css', 'display', 'block');
        });
    });

    it('should not have any fields side by side on mobile screens', () => {
        cy.get('.checkout-form .form-field').each(($field, index, $list) => {
            if (index < $list.length - 1) {
                const nextField = $list[index + 1];
                const fieldPosition = $field[0].getBoundingClientRect();
                const nextFieldPosition = nextField.getBoundingClientRect();
                expect(nextFieldPosition.top).to.be.greaterThan(fieldPosition.bottom);
            }
        });
    });
});
